INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Bedienungsanleitung ohne Schritte sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Schritte geben Struktur"}, {"text": "Ja", "correct": false, "because": "Fehlende Klarheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Bedienungsanleitung?', 3, '[{"text": "Nutzerunterstützung", "correct": true, "because": "Fördert Verständnis"}, {"text": "Code-Dokumentation", "correct": false, "because": "Entwicklerfokus"}, {"text": "Hardware-Optimierung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer guten Anleitung?', 5, '[{"text": "Schritt-für-Schritt", "correct": true, "because": "Klare Abfolge"}, {"text": "Bilder", "correct": true, "because": "Visuelle Unterstützung"}, {"text": "Technischer Jargon", "correct": false, "because": "Verwirrt Laien"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anleitungen brauchen Bilder. b) Text allein reicht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bilder helfen, Text nicht immer genug"}, {"text": "Beides stimmt", "correct": false, "because": "b) oft unzureichend"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) meist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Bedienungsanleitung?', 4, '[{"text": "Klarheit", "correct": false, "because": "Essenziell für Nutzer"}, {"text": "Struktur", "correct": false, "because": "Gibt Orientierung"}, {"text": "Entwicklerdetails", "correct": true, "because": "Nicht nutzerrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anleitungen immer lang sein müssen?', 2, '[{"text": "Nein", "correct Wahr/Falsch-Fragen": true, "because": "Kürze oft effektiver"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Format wähle ich für eine Anleitung?', 3, '[{"text": "PDF", "correct": true, "because": "Universell zugänglich"}, {"text": "Code-Skript", "correct": false, "because": "Nicht nutzerfreundlich"}, {"text": "E-Mail", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen eine Anleitung effektiv?', 5, '[{"text": "Verständlichkeit", "correct": true, "because": "Nutzerfokus"}, {"text": "Beispiele", "correct": true, "because": "Praxisnah"}, {"text": "Technische Tiefe", "correct": false, "because": "Verwirrt Laien"}, {"text": "Hohe Auflösung", "correct": false, "because": "Bildspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anleitungen sind nur für Anfänger. b) Profis brauchen sie nicht. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "Alle profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht exklusiv"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Bedienungsanleitung?', 4, '[{"text": "Schritte", "correct": false, "because": "Kern der Anleitung"}, {"text": "Klartext", "correct": false, "because": "Verständnis nötig"}, {"text": "Quellcode", "correct": true, "because": "Nicht nutzerrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Anleitungen nur schriftlich?', 2, '[{"text": "Nein", "correct": true, "because": "Bilder oder Videos möglich"}, {"text": "Ja", "correct": false, "because": "Multimedia üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten verbessern eine Anleitung?', 4, '[{"text": "Screenshots", "correct": true, "because": "Visuelle Klarheit"}, {"text": "Nummerierte Schritte", "correct": true, "because": "Struktur geben"}, {"text": "Kernel-Details", "correct": false, "because": "Zu technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anleitungen nur einmal erstellt werden. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Updates nötig"}, {"text": "Ja", "correct": false, "because": "Software ändert sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Anleitung?', 3, '[{"text": "Nutzerfreundlichkeit", "correct": true, "because": "Fördert Nutzung"}, {"text": "Technische Präzision", "correct": false, "because": "Sekundär"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anleitungen brauchen Struktur. b) Chaos ist akzeptabel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Chaos verwirrt"}, {"text": "Beides stimmt", "correct": false, "because": "b) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Anleitung?', 5, '[{"text": "Fehlerreduktion", "correct": true, "because": "Klarheit hilft"}, {"text": "Zeitersparnis", "correct": true, "because": "Effiziente Nutzung"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Technische Tiefe", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Anleitung unwichtig?', 3, '[{"text": "Verständlichkeit", "correct": false, "because": "Kern der Anleitung"}, {"text": "Schritte", "correct": false, "because": "Gibt Richtung"}, {"text": "Schriftfarbe", "correct": true, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Anleitungen Schulungen?', 3, '[{"text": "Nein", "correct": true, "because": "Ergänzen sich"}, {"text": "Ja", "correct": false, "because": "Schulung tiefer"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anleitungen nur für Software sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für Anleitungen entscheidend?', 4, '[{"text": "Klarheit", "correct": true, "because": "Fördert Verständnis"}, {"text": "Code-Beispiele", "correct": false, "because": "Entwicklerfokus"}, {"text": "Hohe Auflösung", "correct": false, "because": "Bildspezifisch"}]');
